import { type } from '../../../shared/utility/utilityHelpers';
export const ActionTypes = {
  GET_RATING_REVIEW_LIST: type('[List] Do Rating Review list'),
  GET_RATING_REVIEW_LIST_SUCCESS: type('[List] Do Rating Review list Success'),
  GET_RATING_REVIEW_LIST_FAIL: type('[List] Do Rating Review list Fail'),
  GET_RATING_REVIEW_COUNT_LIST: type('[List Count] Do Rating Review Count list'),
  GET_RATING_REVIEW_COUNT_LIST_SUCCESS: type('[List Count] Do Rating Review Count list Success'),
  GET_RATING_REVIEW_COUNT_LIST_FAIL: type('[List Count] Do Rating Review  Count list Fail')
}; // product list action

export class GetRatingReviewAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.GET_RATING_REVIEW_LIST;
  }

}
export class GetRatingReviewSuccessAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.GET_RATING_REVIEW_LIST_SUCCESS;
  }

}
export class GetRatingReviewFailAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.GET_RATING_REVIEW_LIST_FAIL;
  }

} // product list count action

export class GetRatingReviewCountAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.GET_RATING_REVIEW_COUNT_LIST;
  }

}
export class GetRatingReviewCountSuccessAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.GET_RATING_REVIEW_COUNT_LIST_SUCCESS;
  }

}
export class GetRatingReviewCountFailAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.GET_RATING_REVIEW_COUNT_LIST_FAIL;
  }

}
